"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1147-10-25:0":{"b": ["Król Portugalii Afonso Henriques zdobył Lizbonę od Almorawidów przy pomocy krzyżowców", "f0e4bee4"], "d": ["Po oblężeniu rozpoczętym 1 lipca 1147 garnizon zgodził się 21 października poddać na warunkach swobodnego wyjścia, a bramy otwarto cztery dni później; Lizbona stała się stolicą Portugalii.", "4eea513d"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1148-01-01:0":{"b": ["Hrabstwo Katalonii zdobyło Tortosę (Turtusza)", "fd6c71f8"], "d": ["W czasie rozpadu władzy Almorawidów hrabstwo Katalonii w 1148 r. zdobyło Tortosę.", "344ea86c"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1148-05-22:0":{"b": ["W Andalusii skończyło się panowanie Almorawidów (Jahja al-Massufi zmarł w Granadzie)", "f284a920"], "d": ["Wraz ze śmiercią w Granadzie (543/1148) namiestnika Andalusii Jahji ibn Alego al-Massufiego z rodu Banu Ganija, usiłującego odbudować panowanie almorawidzkie, skończyło się panowanie Almorawidów w Andalusii.", "d03b1ddc"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1150-04-30:0":{"b": ["Abd al-Mumin założył w Rabacie (Ribat al-Fath) obóz na potrzeby podbojów w Andalusii", "7429c45e"], "d": ["Abd al-Mumin al-Kumi założył w roku 545 (1150) obóz w miejscu ribatu, aby służył jako baza wojskowa dla podbojów w Andalusii; miasto stało się później Rabatem.", "c675c9d1"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1152-01-01:0":{"b": ["Bidżaja weszła pod panowanie Almohadów", "17fb2091"], "d": ["Bidżaja, pozostała po Hammadydach, weszła w 1152 roku pod panowanie Almohadów.", "86e00769"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1156-01-01:0":{"b": ["Granada weszła pod panowanie Almohadów", "a6d77491"], "d": ["Po rozpadzie almorawidzkiej Andalusii Granada weszła pod władzę Almohadów (TDV «Gırnata»: panowanie almohadzkie 551/1156).", "a4e8c0ca"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1160-01-21:0":{"b": ["Almohadzi odbili Mahdiję od Normanów", "a195fa3d"], "d": ["Mahdija została za namową Hasana ibn Alego odzyskana od Normanów 10 muharrama 555 (21 stycznia 1160) i oddana almohadzkiemu namiestnikowi.", "96c396ce"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1163-01-01:0":{"b": ["Po śmierci Abd al-Mumina jego syn Jusuf ibn Abd al-Mumin zostaje kalifem (1163-1184).", "dfcc2ec9"], "d": ["Po śmierci Abd al-Mumina jego syn Jusuf ibn Abd al-Mumin zostaje kalifem (1163-1184).", "dfcc2ec9"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1163-05-16:0":{"b": ["Abd al-Mumin zmarł w Salé; następcą został Abu Jakub Jusuf", "231a4a53"], "d": ["Abd al-Mumin, który przybył do Ribat al-Fath na wyprawę andaluzyjską, zachorował i zmarł w Salé 10 dżumada II 558 (16 maja 1163); przygotowania wojskowe pozostały niedokończone, kalifem został jego syn Jusuf.", "58390143"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1183-04-26:0":{"b": ["Jusuf ibn Abd al-Mumin oblegał Santarém i Lizbonę (Uszbuna)", "1da17da0"], "d": ["Współdziałając z Kastylią, Jusuf w roku 579 (1183) oblegał najpierw Santarém (Szanterin), a następnie Lizbonę (Uszbuna), aby ukarać Portugalczyków nękających miasta muzułmańskie; ciężko ranny zmarł, wyprawa pozostała niedokończona.", "cbbc3194"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1184-01-01:0":{"b": ["Po śmierci Jusufa wskutek rany odniesionej pod Lizboną kalifem zostaje jego syn Abu Jusuf Jakub al-Mansur (1184-1199).", "81e06088"], "d": ["Po śmierci Jusufa wskutek rany odniesionej pod Lizboną kalifem zostaje jego syn Abu Jusuf Jakub al-Mansur (1184-1199).", "81e06088"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1195-07-18:0":{"b": ["Jakub al-Mansur rozgromił pod Alarcos armię króla Kastylii Alfonsa VIII (według niektórych źródeł 19 lipca).", "a3da63cb"], "d": ["Jakub al-Mansur rozgromił pod Alarcos armię króla Kastylii Alfonsa VIII (według niektórych źródeł 19 lipca).", "a3da63cb"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1196-01-01:0":{"b": ["Marinidzi pod wodzą Abd al-Hakka ibn Mahjuu utworzyli niezależny emirat w Maghribie Dalekim", "2646fdc2"], "d": ["Po śmierci Mahjuu jego syn Abu Muhammad Abd al-Hakk objął w 592 (1196) władzę jako założyciel dynastii; Marinidzi żyli niezależnie w Maghribie Dalekim od 1196 roku.", "8ee8eb1b"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1212-07-16:0":{"b": ["Kalif an-Nasir ponosi klęskę pod Las Navas de Tolosa (Ikab) z połączoną armią Kastylii, Aragonii i Nawarry; potęga almohadzka w Andalusii upada.", "4e6c8887"], "d": ["Kalif an-Nasir ponosi klęskę pod Las Navas de Tolosa (Ikab) z połączoną armią Kastylii, Aragonii i Nawarry; potęga almohadzka w Andalusii upada.", "4e6c8887"]},
