"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1229-11-20:0":{"b": ["Hafsyda Abu Zakarijja ogłosił niepodległość od Almohadów", "d1f63c2f"], "d": ["Abu Zakarijja na początku roku 627, twierdząc, że wierzenia kalifa almohadzkiego Idrisa al-Mamuna są sprzeczne z sunnizmem, przerwał chutbę i ogłaszając niepodległość z tytułem „emir” stał się faktycznym założycielem dynastii Hafsydów.", "74908f3f"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1235-01-01:0":{"b": ["Jaghmurasan ibn Zajjan założył w Tlemcenie dynastię Abdalwadydów (Zajjanidów)", "5c80da4e"], "d": ["W okresie osłabienia Almohadów przywódca Berberów Banu Abd al-Wad Jaghmurasan ibn Zajjan założył w Tlemcenie dynastię (632/1235).", "7f35119e"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1236-01-01:0":{"b": ["Ferdynand III zdobył Kordobę", "1431c9e8"], "d": ["Osłabiona Kordoba została w 1236 roku bez trudu zajęta przez króla Kastylii i Leónu Ferdynanda III; po panowaniu Hudydów miasto weszło pod władzę chrześcijańską.", "883b568e"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1246-01-01:0":{"b": ["Galib-Billah uznał zwierzchność Kastylii i opuścił Jaén", "754718f2"], "d": ["Założyciel dynastii Nasrydów Muhammad I, bezradny w obronie Jaén, podpisał układ, na mocy którego uznał zwierzchność króla Kastylii, opuścił Jaén i niektóre zamki oraz zobowiązał się płacić roczny trybut (643/1246).", "28a8266d"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1255-02-10:0":{"b": ["Marinidzi pokonali pod Fezem 80-tysięczną armię almohadzką", "d88fb0f0"], "d": ["Abu Jahja Abu Bakr w roku 653 (1255) rozbił armię almohadzką pod Fezem; władza Almohadów ograniczyła się do okolic Marrakeszu.", "b1248952"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1263-01-01:0":{"b": ["Abu Jusuf Jakub oblegał Marrakesz, lecz go nie zdobył", "8140e358"], "d": ["Sułtan Marinidów Abu Jusuf Jakub oblegał w roku 661 (1263) z wielką armią stolicę Almohadów Marrakesz, lecz nie zdołał go zdobyć.", "11966886"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1264-10-24:0":{"b": ["Mieszkańcy Murcji zbuntowali się za namową Nasrydów", "ee46ead4"], "d": ["Za namową władców nasrydzkich mieszkańcy Murcji w 663 (1264-65) raz jeszcze zbuntowali się przeciw Kastylii.", "4feae798"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1266-01-01:0":{"b": ["Król Aragonii Jakub I zdobył Murcję w imieniu Kastylii", "b9b3701f"], "d": ["Król Aragonii Jakub I, który na wezwanie Kastylijczyków przybył z pomocą, zajął zbuntowaną Murcję po dwóch latach (około 1266); Alfons X kazał muzułmanom opuścić centrum miasta w ciągu czterdziestu dni.", "049fb942"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1269-09-09:0":{"b": ["Sułtan Marinidów Abu Jusuf wkroczył do Marrakeszu; państwo Almohadów upadło", "a0d8bd46"], "d": ["Sułtan Marinidów Abu Jusuf Jakub wkroczył do Marrakeszu 10 muharrama 668 (9 września 1269) i przebywał w nim siedem miesięcy; kalif almohadzki Abu Dabbus i pozostali w Marrakeszu dostojnicy almohadzcy zostali wówczas usunięci.", "dea7284f"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1275-09-08:0":{"b": ["Marinidzi pokonali pod Éciją (Isticca) armię kastylijską Dona Nuño de Lary", "77d0e14e"], "d": ["Abu Jusuf Jakub przeprawił się do Andalusii i rozgromił armię kastylijską pod Isticcą koło Kordoby (15 rabi al-awwal 674 / 8 września 1275); zdobył wielu jeńców i łupy.", "94faa00f"]},
